-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): decision capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- BEGINNER
--   Fields read with the switch on: ab_develop_chance_emv_musd,
--   ab_drill_chance_emv_musd, ab_root_emv_musd, ab_farm_out_value_musd,
--   ab_drill_value_no_sell_option_musd, ab_drill_value_success_moved_musd.
--   The builder prints $MM at 2 decimals and the diagram whole $MM; the prompt
--   asks 4.
--   APPENDED: Read the figures in the Decision Tree Builder with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- ADVANCED
--   Fields read with the switch on: ab_mc_linked_root_emv_musd,
--   ab_mc_linked_decision_advantage_musd.
--   The builder prints $MM at 2 decimals and the brief at 1; the prompt asks 4.
--   APPENDED: Read the figures in the Decision Tree Builder and the Decision
--   Studio with their Full precision switch on (at the top of each page): they
--   print them to the precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/decision.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
begin
  -- decision / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'decision' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w3 decision refused: decision/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'bc720e2cda65db84884ba78e294b6fd9' and fields = '[{"key": "ab_develop_chance_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the development chance node after a success, before the development cost", "expected": 469.386}, {"key": "ab_drill_chance_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the drill chance node, before the drill cost", "expected": 106.196}, {"key": "ab_root_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Root EMV of the prospect decision", "expected": 58.896}, {"key": "ab_farm_out_value_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Farm out", "expected": 48.611999999999995}, {"key": "ab_drill_value_no_sell_option_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Drill if Sell is not available after a success", "expected": 54.59882000000003}, {"key": "ab_drill_value_success_moved_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Drill with the success probability at 0.3 and the dry hole taking the difference", "expected": 37.88199999999999}]'::jsonb then 'old'
              when md5(prompt) = '21a7bf7e4188d4ac9d1dcbba69cd1432' and fields = '[{"key": "ab_develop_chance_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the development chance node after a success, before the development cost", "expected": 469.386}, {"key": "ab_drill_chance_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the drill chance node, before the drill cost", "expected": 106.196}, {"key": "ab_root_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Root EMV of the prospect decision", "expected": 58.896}, {"key": "ab_farm_out_value_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Farm out", "expected": 48.611999999999995}, {"key": "ab_drill_value_no_sell_option_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Drill if Sell is not available after a success", "expected": 54.59882000000003}, {"key": "ab_drill_value_success_moved_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Drill with the success probability at 0.3 and the dry hole taking the difference", "expected": 37.88199999999999}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'decision' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w3 decision refused: decision/beginner matches neither its post-W1 form (prompt md5 bc720e2cda65db84884ba78e294b6fd9) nor its W3 form (prompt md5 21a7bf7e4188d4ac9d1dcbba69cd1432), with the fields this file was generated against';
  end if;

  -- decision / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'decision' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w3 decision refused: decision/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '9c474d00ca4f4b701116d084e1d22d06' and fields = '[{"key": "ab_three_reading_evii_musd", "tol": 0.001, "unit": "million USD", "label": "Gross EVII of the three-reading survey", "expected": 25.44400000000003}, {"key": "ab_three_reading_mixed_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the best action after a Mixed reading of the three-reading survey", "expected": 52.455084217092946}, {"key": "ab_mc_linked_root_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Root EMV of the prospect tree with the Large payoff linked to the Monte Carlo summary", "expected": 72.10204}, {"key": "ab_mc_linked_decision_advantage_musd", "tol": 0.001, "unit": "million USD", "label": "Decision advantage row of the decision brief for that linked tree", "expected": 23.490040000000008}, {"key": "ab_analyzer_evpi_two_action_musd", "tol": 0.001, "unit": "million USD", "label": "EVPI the VOI Analyzer reports for this lottery, unrounded (Drill or Do Not Drill)", "expected": 54.960000000000036}, {"key": "ab_max_strong_chance_consistent_pct", "tol": 0.001, "unit": "percent", "label": "Largest Strong indicator chance that passes the consistency check with the typed posteriors", "expected": 39.058823529411754}]'::jsonb then 'old'
              when md5(prompt) = '9099fda79bc00d69eaef2d67fad28009' and fields = '[{"key": "ab_three_reading_evii_musd", "tol": 0.001, "unit": "million USD", "label": "Gross EVII of the three-reading survey", "expected": 25.44400000000003}, {"key": "ab_three_reading_mixed_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the best action after a Mixed reading of the three-reading survey", "expected": 52.455084217092946}, {"key": "ab_mc_linked_root_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Root EMV of the prospect tree with the Large payoff linked to the Monte Carlo summary", "expected": 72.10204}, {"key": "ab_mc_linked_decision_advantage_musd", "tol": 0.001, "unit": "million USD", "label": "Decision advantage row of the decision brief for that linked tree", "expected": 23.490040000000008}, {"key": "ab_analyzer_evpi_two_action_musd", "tol": 0.001, "unit": "million USD", "label": "EVPI the VOI Analyzer reports for this lottery, unrounded (Drill or Do Not Drill)", "expected": 54.960000000000036}, {"key": "ab_max_strong_chance_consistent_pct", "tol": 0.001, "unit": "percent", "label": "Largest Strong indicator chance that passes the consistency check with the typed posteriors", "expected": 39.058823529411754}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'decision' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w3 decision refused: decision/advanced matches neither its post-W1 form (prompt md5 9c474d00ca4f4b701116d084e1d22d06) nor its W3 form (prompt md5 9099fda79bc00d69eaef2d67fad28009), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w3 decision: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 decision refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'The ABALAMA prospect, in the Decision Tree Builder (money in million USD, already discounted). Root decision with three branches. Drill, cost 47.3, leads to a chance node: Success probability 0.37, Marginal 0.21 paying 96.4, Dry hole 0.42 paying -31.8. After a Success there is a decision: Develop, cost 212.6, leads to a chance node Large probability 0.62 paying 684.2 and Small 0.38 paying 118.9; or Sell paying 268.4. Farm out, no cost, leads to a chance node with the same three probabilities paying 118.5, 22.7 and 0. Walk away pays 0. Read six values. Money to four decimals in million USD. Read the figures in the Decision Tree Builder with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'decision' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 decision refused: decision/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '21a7bf7e4188d4ac9d1dcbba69cd1432' and fields = '[{"key": "ab_develop_chance_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the development chance node after a success, before the development cost", "expected": 469.386}, {"key": "ab_drill_chance_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the drill chance node, before the drill cost", "expected": 106.196}, {"key": "ab_root_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Root EMV of the prospect decision", "expected": 58.896}, {"key": "ab_farm_out_value_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Farm out", "expected": 48.611999999999995}, {"key": "ab_drill_value_no_sell_option_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Drill if Sell is not available after a success", "expected": 54.59882000000003}, {"key": "ab_drill_value_success_moved_musd", "tol": 0.001, "unit": "million USD", "label": "Branch value of Drill with the success probability at 0.3 and the dry hole taking the difference", "expected": 37.88199999999999}]'::jsonb) from public.academy_capstones where app_slug = 'decision' and tier = 'beginner' and active) is not true then
    raise exception 'w3 decision refused: decision/beginner does not read back as its W3 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'The ABALAMA prospect, in the Decision Tree Builder (money in million USD, already discounted). Root decision with three branches. Drill, cost 47.3, leads to a chance node: Success probability 0.37, Marginal 0.21 paying 96.4, Dry hole 0.42 paying -31.8. After a Success there is a decision: Develop, cost 212.6, leads to a chance node Large probability 0.62 paying 684.2 and Small 0.38 paying 118.9; or Sell paying 268.4. Farm out, no cost, leads to a chance node with the same three probabilities paying 118.5, 22.7 and 0. Walk away pays 0. The ABALAMA lottery (money in million USD). Outcomes and prior probabilities: Large 0.18, Modest 0.34, Dry 0.48. Actions, payoffs in outcome order: Drill cost 62.5 paying 735 / 88 / -52; Farm out cost 0 paying 142 / 34.6 / 0; Relinquish cost 0 paying 0 / 0 / 0. A survey costing 11.4 reads Strong or Weak with likelihoods P(reading | outcome), in outcome order: Strong 0.78 / 0.46 / 0.17; Weak 0.22 / 0.54 / 0.83. A second survey design reads Strong, Mixed or Weak with likelihoods, in outcome order: Strong 0.66 / 0.31 / 0.09; Mixed 0.23 / 0.44 / 0.27; Weak 0.11 / 0.25 / 0.64; value it with no cost. The tree''s Large development payoff is linked to a saved Monte Carlo run whose NPV summary is mean 760.5, P90 (low case) 455, P50 721.3, P10 (high case) 1098.4. In the VOI Analyzer the lottery is entered with Drill as the decision and the Strong and Weak readings as indicators whose outcome chances are typed, in percent and outcome order, Strong 37.1 / 41.3 / 21.6 and Weak 6.4 / 29.5 / 64.1; the Weak indicator chance is always 100 less the Strong indicator chance, and the stated outcome chances are the lottery''s priors in percent. Read six values. Money to four decimals in million USD; the indicator chance in percent to four decimals. Read the figures in the Decision Tree Builder and the Decision Studio with their Full precision switch on (at the top of each page): they print them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'decision' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 decision refused: decision/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '9099fda79bc00d69eaef2d67fad28009' and fields = '[{"key": "ab_three_reading_evii_musd", "tol": 0.001, "unit": "million USD", "label": "Gross EVII of the three-reading survey", "expected": 25.44400000000003}, {"key": "ab_three_reading_mixed_emv_musd", "tol": 0.001, "unit": "million USD", "label": "EMV of the best action after a Mixed reading of the three-reading survey", "expected": 52.455084217092946}, {"key": "ab_mc_linked_root_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Root EMV of the prospect tree with the Large payoff linked to the Monte Carlo summary", "expected": 72.10204}, {"key": "ab_mc_linked_decision_advantage_musd", "tol": 0.001, "unit": "million USD", "label": "Decision advantage row of the decision brief for that linked tree", "expected": 23.490040000000008}, {"key": "ab_analyzer_evpi_two_action_musd", "tol": 0.001, "unit": "million USD", "label": "EVPI the VOI Analyzer reports for this lottery, unrounded (Drill or Do Not Drill)", "expected": 54.960000000000036}, {"key": "ab_max_strong_chance_consistent_pct", "tol": 0.001, "unit": "percent", "label": "Largest Strong indicator chance that passes the consistency check with the typed posteriors", "expected": 39.058823529411754}]'::jsonb) from public.academy_capstones where app_slug = 'decision' and tier = 'advanced' and active) is not true then
    raise exception 'w3 decision refused: decision/advanced does not read back as its W3 form';
  end if;

  raise notice 'w3 decision: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
